class KunSpoilerStrings {
  const KunSpoilerStrings({
    required this.copyCode,
    required this.reveal,
  });

  /// `en`: Copy code
  final String copyCode;

  /// `en`: Spoiler — click or press Enter to reveal
  final String reveal;
}

/// Strings for `KunSteps`.
class KunStepsStrings {
  const KunStepsStrings({
    required String completed,
    required String current,
    required String pending,
    required String error,
  })  : _completed = completed,
        _current = current,
        _pending = pending,
        _error = error;

  final String _completed;

  final String _current;

  final String _pending;

  final String _error;

  /// `en`: Completed: {title}
  String completed({required Object title}) =>
      _completed.replaceAll('{title}', '$title');

  /// `en`: Current step: {title}
  String current({required Object title}) =>
      _current.replaceAll('{title}', '$title');

  /// `en`: Not started: {title}
  String pending({required Object title}) =>
      _pending.replaceAll('{title}', '$title');

  /// `en`: Error: {title}
  String error({required Object title}) =>
      _error.replaceAll('{title}', '$title');
}

/// Strings for `KunTagInput`.
class KunTagInputStrings {
  const KunTagInputStrings({
    required String tag,
    required String removeTag,
  })  : _tag = tag,
        _removeTag = removeTag;

  final String _tag;

  final String _removeTag;

  /// `en`: Tag {tag}
  String tag({required Object tag}) => _tag.replaceAll('{tag}', '$tag');

  /// `en`: Remove tag {tag}
  String removeTag({required Object tag}) =>
      _removeTag.replaceAll('{tag}', '$tag');
}

/// Strings for `KunTextSelection`.
class KunTextSelectionStrings {
  const KunTextSelectionStrings({
    required this.copy,
    required this.cut,
    required this.paste,
    required this.selectAll,
    required this.share,
    required this.lookUp,
    required this.searchWeb,
