  /// `en`: Copy
  final String copy;

  /// `en`: Cut
  final String cut;

  /// `en`: Paste
  final String paste;

  /// `en`: Select all
  final String selectAll;

  /// `en`: Share
  final String share;

  /// `en`: Look Up
  final String lookUp;

  /// `en`: Search Web
  final String searchWeb;
}

/// Strings for `KunUpload`.
